(function ($) {
	'use strict';

	function initAccordion($wrapper) {
		const autoOpenAttr    = $wrapper.attr('data-auto-open');
		const closeableAttr   = $wrapper.attr('data-closeable');
		const closeOthersAttr = $wrapper.attr('data-close-others');
		const closedIconClass = $wrapper.attr('data-closed-icon');
		const openIconClass   = $wrapper.attr('data-open-icon');

		// New data attributes
		const openEvent       = $wrapper.attr('data-open-event') || 'click';
		const animSpeedAttr   = $wrapper.attr('data-anim-speed');
		const animSpeed       = animSpeedAttr ? parseInt(animSpeedAttr, 10) : 200;

		const autoOpenIndex = autoOpenAttr ? parseInt(autoOpenAttr, 10) - 1 : -1;
		const isCloseable   = closeableAttr !== 'no';
		const closeOthers   = closeOthersAttr !== 'no';

		const $items = $wrapper.find('.responsive-accordion > li');

		// Helper function to update Font Awesome classes dynamically
		function updateIcon($head, isOpen) {
			if (!closedIconClass || !openIconClass) return;

			const $icon = $head.find('.responsive-accordion-icon i');
			if ($icon.length) {
				if (isOpen) {
					$icon.removeClass(closedIconClass).addClass(openIconClass);
				} else {
					$icon.removeClass(openIconClass).addClass(closedIconClass);
				}
			}
		}

		// Initial Auto-Open state check
		$items.each(function (index) {
			const $head  = $(this).find('.responsive-accordion-head');
			const $panel = $(this).find('.responsive-accordion-panel');

			if (index === autoOpenIndex) {
				$head.addClass('active');
				$panel.show();
				updateIcon($head, true);
			} else {
				$head.removeClass('active');
				$panel.hide();
				updateIcon($head, false);
			}
		});

		// Core Toggle Action
		function toggleItem($head) {
			const $panel       = $head.next('.responsive-accordion-panel');
			const $currentItem = $head.parent('li');
			const isActive     = $head.hasClass('active');

			if (isActive && !isCloseable) {
				return;
			}

			// Close other items
			if (closeOthers) {
				$items.not($currentItem).each(function () {
					const $otherHead = $(this).find('.responsive-accordion-head');
					$otherHead.removeClass('active');
					$otherHead.next('.responsive-accordion-panel').stop(true, true).slideUp(animSpeed);
					updateIcon($otherHead, false);
				});
			}

			// Toggle current item
			if (isActive) {
				$head.removeClass('active');
				$panel.stop(true, true).slideUp(animSpeed);
				updateIcon($head, false);
			} else {
				$head.addClass('active');
				$panel.stop(true, true).slideDown(animSpeed);
				updateIcon($head, true);
			}
		}

		// Unbind previous event handlers to prevent duplicate execution during re-init
		$wrapper.off('click mouseenter', '.responsive-accordion-head');

		// Bind Click or Hover Event
		if (openEvent === 'hover') {
			$wrapper.on('mouseenter', '.responsive-accordion-head', function () {
				toggleItem($(this));
			});
		} else {
			$wrapper.on('click', '.responsive-accordion-head', function (e) {
				e.preventDefault();
				toggleItem($(this));
			});
		}
	}

	// Initialize on page load
	$(document).ready(function () {
		$('.tc-accordion-wrapper').each(function () {
			initAccordion($(this));
		});
	});

	// Support re-initialization (e.g., WordPress Live Preview / Gutenberg / AJAX)
	$(document).on('tc_accordion_reinit', function (e, targetWrapper) {
		if (targetWrapper) {
			initAccordion($(targetWrapper));
		} else {
			$('.tc-accordion-wrapper').each(function () {
				initAccordion($(this));
			});
		}
	});

	document.addEventListener('DOMContentLoaded', function () {
	    // 1. Keyboard Navigation (Enter and Space key trigger)
	    document.addEventListener('keydown', function (e) {
	        if ((e.key === ' ' || e.key === 'Enter') && e.target.classList.contains('responsive-accordion-head')) {
	            e.preventDefault(); // Stop page scrolling on Spacebar
	            e.target.click();   // Trigger click event
	        }
	    });

	    // 2. Dynamic ARIA Expanded Sync
	    document.querySelectorAll('.responsive-accordion-head').forEach(function (head) {
	        head.addEventListener('click', function () {
	            var wrapper = head.closest('.tc-accordion-wrapper');
	            var isCloseOthers = wrapper && wrapper.getAttribute('data-close-others') === 'yes';

	            if (isCloseOthers) {
	                wrapper.querySelectorAll('.responsive-accordion-head').forEach(function (otherHead) {
	                    otherHead.setAttribute('aria-expanded', 'false');
	                });
	            }

	            setTimeout(function () {
	                var isActive = head.classList.contains('active');
	                head.setAttribute('aria-expanded', isActive ? 'true' : 'false');
	            }, 50);
	        });
	    });
	});
	

})(jQuery);